import { useState, useEffect, useRef } from 'react';
import { useNavigate, useParams, Routes, Route } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../components/Toast';
import ConfirmDialog from '../components/ConfirmDialog';
import Spinner from '../components/Spinner';
import {
  getAlbumsByUser, createAlbum, deleteAlbum,
  getPhotosByAlbum, createPhoto, updatePhoto, deletePhoto
} from '../services/api';
import '../styles/Albums.css';

function AlbumList() {
  const { userId } = useParams();
  const navigate = useNavigate();
  const toast = useToast();

  const [albums, setAlbums] = useState([]);
  const [covers, setCovers] = useState({});
  const [loading, setLoading] = useState(true);
  const [searchId, setSearchId] = useState('');
  const [searchTitle, setSearchTitle] = useState('');

  const [showAddForm, setShowAddForm] = useState(false);
  const [newAlbumTitle, setNewAlbumTitle] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);

  // הבאת האלבומים של המשתמש הפעיל לפי דרישות המטלה
  useEffect(() => { fetchAlbums(); }, [userId]);

  const fetchAlbums = async () => {
    setLoading(true);
    try {
      const data = await getAlbumsByUser(userId);
      const fetchedAlbums = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      setAlbums(fetchedAlbums);

      fetchedAlbums.forEach(async (album) => {
        try {
          const res = await getPhotosByAlbum(album.id, 1, 1);
          const coverPhotos = Array.isArray(res) ? res : (Array.isArray(res?.data) ? res.data : []);
          if (coverPhotos.length > 0) {
            setCovers(prev => ({ ...prev, [album.id]: coverPhotos[0].url || coverPhotos[0].thumbnailUrl }));
          }
        } catch {}
      });
    } finally {
      setLoading(false);
    }
  };

  // יצירת אלבום חדש עבור המשתמש הפעיל
  const handleAdd = async () => {
    if (!newAlbumTitle.trim()) return;
    try {
      const added = await createAlbum({ userId: userId, title: newAlbumTitle.trim() });
      setAlbums((prev) => [added, ...prev]);
      setNewAlbumTitle('');
      setShowAddForm(false);
      toast('Destination added!');
    } catch {
      toast('Error adding destination', 'error');
    }
  };

  // חיפוש פריטים לפי id וכותרת
  const filtered = albums.filter((a) => {
    if (searchId && !String(a.id).includes(searchId)) return false;
    if (searchTitle && !a.title.toLowerCase().includes(searchTitle.toLowerCase())) return false;
    return true;
  });

  return (
    <div className="albums-page">
      <div className="page-header">
        <div className="header-left">
          <button className="btn-home" onClick={() => navigate(`/users/${userId}`)}>🏠 Home</button>
          <h2>📷 My Destinations</h2>
        </div>
        <button className="btn-add-main" onClick={() => setShowAddForm(!showAddForm)}>
          {showAddForm ? '✕ Close' : '➕ Add Destination'}
        </button>
      </div>

      {showAddForm && (
        <div className="top-add-section">
          <div className="modern-form">
            <input 
              value={newAlbumTitle} 
              onChange={(e) => setNewAlbumTitle(e.target.value)}
              placeholder="Where are we going? (e.g. London 2026)" 
            />
            <button className="btn-primary" onClick={handleAdd}>Save Destination</button>
          </div>
        </div>
      )}

      <div className="albums-toolbar">
        <input placeholder="Search ID" value={searchId} onChange={(e) => setSearchId(e.target.value)} />
        <input placeholder="Search Name" value={searchTitle} onChange={(e) => setSearchTitle(e.target.value)} />
      </div>

      {loading ? <Spinner text="Loading..." /> : (
        <div className="albums-grid">
          {filtered.map((album) => (
            <div key={album.id} className="album-card" onClick={() => navigate(`/users/${userId}/albums/${album.id}/photos`)}>
              {covers[album.id] ? <img className="album-cover-img" src={covers[album.id]} alt="" /> : <div className="album-cover-placeholder">🗺️</div>}
              <div className="album-info">
                <span className="album-title">{album.title}</span>
                <span className="album-id">#{String(album.id).substring(0,4)}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function AlbumPhotos() {
  const { userId, albumId } = useParams();
  const navigate = useNavigate();
  const toast = useToast();
  const fileInputRef = useRef(null);

  const [photos, setPhotos] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [newPhotoTitle, setNewPhotoTitle] = useState('');
  const [newPhotoUrl, setNewPhotoUrl] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [lightbox, setLightbox] = useState(null);

  // הבאת תמונות בשלבים (Pagination)
  useEffect(() => { loadPhotos(1, true); }, [albumId]);

  const loadPhotos = async (pageNum, reset = false) => {
    setLoading(true);
    try {
      const res = await getPhotosByAlbum(albumId, pageNum, 6);
      const fetched = Array.isArray(res) ? res : (Array.isArray(res?.data) ? res.data : []);
      setPhotos((prev) => reset ? fetched : [...prev, ...fetched]);
    } finally {
      setLoading(false);
    }
  };

  // מנגנון מקצועי לכיווץ ודחיסת התמונה בצד הלקוח למניעת שגיאות גודל בשרת
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 800; // הקטנה חכמה לרוחב אידיאלי לגלריה
        const scaleSize = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scaleSize;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

        // ייצוא התמונה המכווצת כמחרוזת Base64 קלילה (באיכות 70%)
        const compressedBase64 = canvas.toDataURL('image/jpeg', 0.7);
        setNewPhotoUrl(compressedBase64);
      };
      img.src = event.target.result;
    };
    reader.onerror = () => { toast('Error reading file', 'error'); };
    reader.readAsDataURL(file);
  };

  // ניהול והוספת תמונות לאלבום
  const handleAddPhoto = async () => {
    if (!newPhotoUrl) {
      toast('Please select an image first', 'error');
      return;
    }
    try {
      const added = await createPhoto({ 
        albumId: albumId, 
        title: newPhotoTitle.trim(), 
        url: newPhotoUrl, 
        thumbnailUrl: newPhotoUrl 
      });
      setPhotos((prev) => [added, ...prev]);
      setNewPhotoUrl(''); setNewPhotoTitle(''); setShowAddForm(false);
      toast('Memory saved!');
    } catch {
      toast('Error saving photo', 'error');
    }
  };

  return (
    <div className="photos-page">
      <div className="photos-header">
        <div className="header-left">
          <button className="btn-back" onClick={() => navigate(`/users/${userId}/albums`)}>← Back</button>
          <h2>Album #{String(albumId).substring(0,4)}</h2>
        </div>
        <button className="btn-add-main" onClick={() => setShowAddForm(!showAddForm)}>
          {showAddForm ? '✕ Close' : '📸 Add Memory'}
        </button>
      </div>

      {showAddForm && (
        <div className="top-add-section">
          <div className="modern-photo-form">
            <div className="upload-zone" onClick={() => fileInputRef.current.click()}>
              {newPhotoUrl ? <img src={newPhotoUrl} className="preview-img" alt="preview" /> : <span>📁 Click to choose image</span>}
              <input type="file" ref={fileInputRef} hidden onChange={handleFileUpload} accept="image/*" />
            </div>
            <div className="form-inputs">
              <input value={newPhotoTitle} onChange={(e) => setNewPhotoTitle(e.target.value)} placeholder="Caption (optional)..." />
              <button className="btn-primary" onClick={handleAddPhoto}>Add to Album</button>
            </div>
          </div>
        </div>
      )}

      <div className="photos-grid">
        {photos.map((photo) => (
          <div key={photo.id} className="photo-card-polaroid">
            <div className="polaroid-img-wrap" onClick={() => setLightbox(photo)}>
              <img src={photo.url} alt="" />
            </div>
            <div className="polaroid-caption">
              <span>{photo.title || 'Untitled Memory'}</span>
              <button className="btn-mini-del" onClick={() => setConfirmDelete(photo.id)}>🗑️</button>
            </div>
          </div>
        ))}
      </div>

      {lightbox && (
        <div className="lightbox-overlay" onClick={() => setLightbox(null)}>
          <div className="lightbox-content">
            <img src={lightbox.url} alt="" />
            <p>{lightbox.title}</p>
          </div>
        </div>
      )}

      {confirmDelete && (
        <ConfirmDialog
          message="Delete this memory?"
          onConfirm={async () => {
            await deletePhoto(confirmDelete);
            setPhotos(prev => prev.filter(p => p.id !== confirmDelete));
            setConfirmDelete(null);
            toast('Deleted', 'error');
          }}
          onCancel={() => setConfirmDelete(null)}
        />
      )}
    </div>
  );
}

export default function Albums() {
  return (
    <Routes>
      <Route index element={<AlbumList />} />
      <Route path=":albumId/photos" element={<AlbumPhotos />} />
    </Routes>
  );
}
